    <style>
        :root{--ink:#15223a;--muted:#66738c;--line:#e8edf5;--paper:#fff;--canvas:#f5f7fb;--blue:#2764f5;--navy:#111d36;--aqua:#23c4a5;--amber:#f6a51b;--violet:#7658e8}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px 'DM Sans',sans-serif}.shell{min-height:100vh;display:grid;grid-template-columns:255px 1fr}.sidebar{background:var(--navy);color:#cbd5e9;padding:25px 15px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;color:#fff;font:800 18px 'Plus Jakarta Sans';padding:0 10px 32px}.brand-mark{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(135deg,#3c82ff,#7f57f5)}.brand small{display:block;color:#91a0bd;font:500 10px 'DM Sans';letter-spacing:.08em;text-transform:uppercase;margin-top:2px}.nav-label{color:#71809d;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;padding:0 12px;margin:16px 0 8px}.nav a{display:flex;align-items:center;gap:11px;padding:10px 12px;border-radius:10px;color:#b7c2d9;text-decoration:none;margin:2px 0;font-weight:500}.nav a:hover,.nav a.active{color:#fff;background:#ffffff14}.nav a.active{background:linear-gradient(90deg,#316cf8,#316cf8bb)}.nav i{font-style:normal;width:18px;text-align:center}.sidebar-footer{margin-top:auto;border-top:1px solid #ffffff12;padding:17px 10px 0}.admin-mini{display:flex;align-items:center;gap:9px}.avatar{width:34px;height:34px;border-radius:50%;background:#f2bb6d;display:grid;place-items:center;color:#563309;font-weight:800}.admin-mini span{display:block;font-size:12px;color:#91a0bd;margin-top:2px}.content{min-width:0}.topbar{height:78px;background:#fff;border-bottom:1px solid var(--line);padding:0 34px;display:flex;align-items:center;justify-content:space-between}.breadcrumb{color:var(--muted)}.breadcrumb strong{color:var(--ink)}.top-actions{display:flex;align-items:center;gap:13px}.button{border:1px solid var(--line);background:#fff;border-radius:10px;height:38px;padding:0 12px;cursor:pointer;color:var(--ink);text-decoration:none;display:inline-flex;align-items:center;gap:7px;font:600 12px 'DM Sans'}.monitor{color:var(--blue);border-color:#dbe5ff;background:#f7f9ff}.logout{color:#cf4f65}main{padding:33px;max-width:1500px;margin:auto}.welcome{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:27px}.eyebrow{color:var(--blue);font-size:11px;letter-spacing:.09em;text-transform:uppercase;font-weight:800}.welcome h1{font:800 27px 'Plus Jakarta Sans';margin:5px 0 7px}.welcome p{color:var(--muted);margin:0}.date{color:var(--muted);background:#fff;padding:10px 13px;border:1px solid var(--line);border-radius:10px;white-space:nowrap}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.stat{background:#fff;border:1px solid var(--line);border-radius:15px;padding:18px;position:relative;overflow:hidden}.stat:after{content:'';width:67px;height:67px;position:absolute;right:-22px;top:-22px;border-radius:50%;background:var(--wash)}.stat-head{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-weight:600}.stat-icon{width:33px;height:33px;display:grid;place-items:center;border-radius:9px;background:var(--wash);font-size:16px}.stat-value{font:800 26px 'Plus Jakarta Sans';margin:17px 0 5px}.stat-foot{font-size:11px;color:var(--muted)}.positive{color:#15977e;font-weight:700}.section-heading{display:flex;align-items:center;justify-content:space-between;margin:32px 0 14px}.section-heading h2{margin:0;font:800 17px 'Plus Jakarta Sans'}.section-heading p{margin:4px 0 0;color:var(--muted);font-size:12px}.section-heading a{color:var(--blue);text-decoration:none;font-weight:700;font-size:12px}.modules{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.module{min-height:159px;background:#fff;border:1px solid var(--line);border-radius:15px;padding:18px;text-decoration:none;color:var(--ink);transition:.18s transform,.18s box-shadow;position:relative}.module:hover{transform:translateY(-3px);box-shadow:0 13px 30px #25345c12}.module-icon{width:39px;height:39px;display:grid;place-items:center;border-radius:11px;background:var(--module);font-size:19px}.module h3{margin:14px 0 5px;font:700 14px 'Plus Jakarta Sans'}.module p{margin:0;color:var(--muted);font-size:12px;line-height:1.45}.arrow{position:absolute;right:17px;bottom:14px;color:var(--blue);font-size:18px}.badge{position:absolute;top:17px;right:17px;padding:4px 8px;color:var(--badge);background:var(--module);border-radius:20px;font-size:10px;font-weight:800}.work-grid{display:grid;grid-template-columns:1.35fr .9fr;gap:16px}.card{background:#fff;border:1px solid var(--line);border-radius:15px;overflow:hidden}.card-head{display:flex;justify-content:space-between;align-items:center;padding:19px 20px 14px}.card-head h3{margin:0;font:700 15px 'Plus Jakarta Sans'}.card-head a{color:var(--blue);font-size:12px;font-weight:700;text-decoration:none}.table{width:100%;border-collapse:collapse}.table th{text-align:left;background:#fafbfe;padding:10px 20px;color:#7b879d;font-size:10px;text-transform:uppercase;letter-spacing:.07em}.table td{padding:13px 20px;border-top:1px solid #f0f2f7}.person{display:flex;gap:9px;align-items:center}.person-mark{width:29px;height:29px;background:#e9efff;color:#496ed9;border-radius:8px;display:grid;place-items:center;font-weight:800;font-size:11px}.person small{display:block;color:var(--muted);margin-top:2px}.pill{display:inline-block;padding:4px 8px;border-radius:20px;font-size:10px;font-weight:800}.pending{background:#fff4d9;color:#b17200}.siswa{background:#eaf0ff;color:#3f66cf}.guru{background:#e5f8f1;color:#168168}.admin{background:#f1ebff;color:#7658cc}.queue{padding:0 20px 7px}.queue-item{display:flex;align-items:center;gap:12px;border-top:1px solid #f0f2f7;padding:13px 0}.queue-icon{background:#fff3dc;width:33px;height:33px;border-radius:9px;display:grid;place-items:center}.queue-main{flex:1;min-width:0}.queue-main b{display:block;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.queue-main span{color:var(--muted);font-size:11px}.notice{margin-top:16px;display:flex;align-items:flex-start;gap:12px;background:#eff4ff;border:1px solid #dce7ff;border-radius:13px;padding:14px 16px;color:#44577e;font-size:12px;line-height:1.5}.notice b{color:#244eaf}@media(max-width:1100px){.stats{grid-template-columns:repeat(2,1fr)}.modules{grid-template-columns:repeat(2,1fr)}}@media(max-width:780px){.shell{grid-template-columns:1fr}.sidebar{display:none}.topbar{height:62px;padding:0 16px}.breadcrumb{display:none}main{padding:22px 16px}.date{display:none}.work-grid{grid-template-columns:1fr}.table th:nth-child(3),.table td:nth-child(3){display:none}}@media(max-width:480px){.stats,.modules{grid-template-columns:1fr}.monitor{display:none}.welcome h1{font-size:23px}.table th,.table td{padding-left:13px;padding-right:13px}}
    </style>
